local module = {}

-- 获取 TablesProvider
-- @param tableProvider: (name:string)->{} 根据表名称获取表的委托
module.GetTablesProvider = function(tableProvider: (name: string) -> {})
	local tablesProvider = {
		GetTables = function(self)
			return _G.wdm.WuKong.Configs.Tables({
				Resolve = tableProvider,
			})
		end,
	}
	return tablesProvider
end

return module
